import{_ as e,o as l,c as a,a2 as r}from"./chunks/framework.BWuWLRhz.js";const x=JSON.parse('{"title":"設定中心參考","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/user-guide/settings/index.md","filePath":"zh-TW/user-guide/settings/index.md","lastUpdated":1787586465000}'),n={name:"zh-TW/user-guide/settings/index.md"};function s(d,t,i,o,g,h){return l(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="設定中心參考" tabindex="-1">設定中心參考 <a class="header-anchor" href="#設定中心參考" aria-label="Permalink to &quot;設定中心參考&quot;">​</a></h1><p>Lertaro 提供了極其豐富且細緻的個人化設定選項。無論你是想要微調搜尋框的像素級尺寸、自訂全域快速鍵、調整不同磁碟的索引頻率，還是管理第三方外掛模組與工作區，都可以在設定中心中完成。</p><h2 id="_1-視窗特性與即時互動" tabindex="-1">1. 視窗特性與即時互動 <a class="header-anchor" href="#_1-視窗特性與即時互動" aria-label="Permalink to &quot;1. 視窗特性與即時互動&quot;">​</a></h2><ul><li><strong>自適應視窗與全鍵盤操作</strong>：設定視窗支援自由拖曳邊框調整寬高、按兩下標題列最大化，並自動記住你調整的尺寸。</li><li><strong>全域設定模糊搜尋</strong>：設定視窗標題列右上角內建了全域設定搜尋框。搜尋演算法採用與主搜尋相同的 fzf 模糊比對與拼音別名引擎。輸入關鍵字即可跨所有分區（包括外掛模組設定與動態動作）檢索選項，按 Enter 即可瞬間跳轉至目標頁面並閃爍反白該控制項。</li><li><strong>防溢出索引標籤列導覽</strong>：在包含多層子索引標籤頁的分區（如一般、快速鍵、索引等）中，當索引標籤文字較長時兩端會自動呈現捲動箭頭，確保在任何語言環境下索引標籤均能完整檢視。</li></ul><h2 id="_2-設定分區總覽" tabindex="-1">2. 設定分區總覽 <a class="header-anchor" href="#_2-設定分區總覽" aria-label="Permalink to &quot;2. 設定分區總覽&quot;">​</a></h2><p>設定視窗左側導覽列共包含以下十個核心分區：</p><table tabindex="0"><thead><tr><th style="text-align:left;">分區模組</th><th style="text-align:left;">核心管理內容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><a href="./service-status.html">執行狀態</a></strong></td><td style="text-align:left;">背景 Windows 服務的執行狀態、健康度監控，以及 Service / App / Hook 三大處理程序的即時記錄檢視器。</td></tr><tr><td style="text-align:left;"><strong><a href="./index-drives.html">索引管理</a></strong></td><td style="text-align:left;">本機磁碟（NTFS / ReFS / FAT32）、網路共用磁碟機（SMB / NAS）、WSL 子系統發行版、自訂資料夾及三類排除規則。</td></tr><tr><td style="text-align:left;"><strong><a href="./general.html">一般設定</a></strong></td><td style="text-align:left;">開機自啟、硬體加速、IPC 相容服務、搜尋框像素級尺寸配置、主視窗表格欄排序與預覽視窗參數。</td></tr><tr><td style="text-align:left;"><strong><a href="./hotkeys-page.html">快速鍵綁定</a></strong></td><td style="text-align:left;">全域呼出快速鍵、功能快速鍵、外掛模組專屬動作快速鍵，以及前景處理程序黑名單與全螢幕放行規則。</td></tr><tr><td style="text-align:left;"><strong><a href="./plugins.html">外掛模組管理</a></strong></td><td style="text-align:left;">已安裝外掛模組清單、各元件獨立開關、外掛模組表單設定面板，以及 Flow Launcher 社群外掛模組生態管理。</td></tr><tr><td style="text-align:left;"><strong><a href="./localsend.html">LocalSend 傳輸</a></strong></td><td style="text-align:left;">相容 LocalSend 官方用戶端的區域網路無線傳輸通訊協定設定（裝置名稱、連接埠、PIN 碼與自動儲存）。</td></tr><tr><td style="text-align:left;"><strong><a href="./favorites.html">我的最愛</a></strong></td><td style="text-align:left;">常用資料夾、檔案與網址的星標別名收藏，支援拖曳排序與拼音檢索。</td></tr><tr><td style="text-align:left;"><strong><a href="./history.html">搜尋歷程記錄</a></strong></td><td style="text-align:left;">搜尋結果命中歷程與輸入關鍵字歷程的管理、智慧召回及清理。</td></tr><tr><td style="text-align:left;"><strong><a href="./quick-panel.html">快速面板</a></strong></td><td style="text-align:left;">停靠在活動視窗旁的浮動工作區、多來源資料夾聚合、檔案拖入接收與外掛模組動態索引標籤頁。</td></tr><tr><td style="text-align:left;"><strong><a href="./appearance.html">外觀與主題</a></strong></td><td style="text-align:left;">淺色/深色/跟隨系統模式切換，以及自帶與隨包精選主題卡片的即時縮圖預覽。</td></tr><tr><td style="text-align:left;"><strong><a href="./about.html">關於與更新</a></strong></td><td style="text-align:left;">各元件版本號、使用者與機器資料目錄快速直達、資料備份輪轉機制與一鍵無訊息升級。</td></tr></tbody></table><p>以下各章節將按順序列出每一個設定分區的詳細選項、參數範圍與預設行為。</p>',8)])])}const y=e(n,[["render",s]]);export{x as __pageData,y as default};
